package wb;
import android.content.*;import android.os.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class Engine {
 private static Engine instance;public static synchronized Engine get(Context c){if(instance==null)instance=new Engine(c.getApplicationContext());return instance;}
 final RequestJournal journal;public volatile boolean serviceHealth=false,wakeHeld=false;public volatile long serviceUptime=0;
 final Context ctx;final VehicleReader reader;final Tts tts=new Tts();final DoorAudio localAudio;final LocationReader location;JSONObject latestTelemetry=new JSONObject(),signalDiagnostics=new JSONObject();long telemetryReadAt;final Handler main=new Handler(Looper.getMainLooper());ScheduledExecutorService poll;final ExecutorService net=Executors.newFixedThreadPool(2);final AtomicInteger active=new AtomicInteger();final AtomicLong generation=new AtomicLong();
 JSONObject cfg;final LinkedList<JSONObject> history=new LinkedList<>();final Integer[] doors=new Integer[4];final DoorTracker tracker=new DoorTracker();final AtomicLongArray doorGeneration=new AtomicLongArray(4);final ArrayDeque<Runnable> normalQueue=new ArrayDeque<>();boolean draining=false;long lastLocal=0,lastSample=0;final long[] seen={0,0,0,0};String aiStatus="等待事件",lastContext="{}",lastPayload="{}";boolean started=false;long lastSampleNote=0;
 Engine(Context c){ctx=c;location=new LocationReader(c);localAudio=new DoorAudio(c);localAudio.diagnostic=(message)->main.post(()->note("本地音频",message));try{JSONArray old=new JSONArray(c.getSharedPreferences("diagnostics",0).getString("history","[]"));for(int i=0;i<old.length();i++)history.add(old.getJSONObject(i));}catch(Exception ignored){}tts.diagnostic=(message)->main.post(()->note("TTS",message));journal=new RequestJournal(new File(c.getFilesDir(),"requests.json"));reader=new VehicleReader(c);try{cfg=new JSONObject(c.getSharedPreferences("assistant",0).getString("config","{}"));}catch(Exception e){cfg=new JSONObject();}defaults();if(!c.getSharedPreferences("assistant",0).getBoolean("requestViewV2",false)){put(cfg,"logContext",true);c.getSharedPreferences("assistant",0).edit().putString("config",cfg.toString()).putBoolean("requestViewV2",true).apply();}
 if(!c.getSharedPreferences("assistant",0).getBoolean("personalImported",false)){
  try(java.io.InputStream input=c.getAssets().open("personal-config.json")){
   java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=input.read(b))!=-1){output.write(b,0,n);if(output.size()>16384)throw new java.io.IOException();}
   JSONObject personal=new JSONObject(output.toString("UTF-8"));for(String key:new String[]{"baseUrl","model","key","ai"})if(personal.has(key))put(cfg,key,personal.get(key));
   c.getSharedPreferences("assistant",0).edit().putString("config",cfg.toString()).putBoolean("personalImported",true).apply();
  }catch(Exception ignored){}
 }
 }
 void put(JSONObject j,String k,Object v){try{j.put(k,v);}catch(Exception ignored){}}
 static final String[] DOOR_KEYS={"driver","passenger","rearLeft","rearRight"};static final String[] DOOR_NAMES={"主驾车门","副驾车门","左后车门","右后车门"};
 void defaults(){if(!cfg.has("profileName"))put(cfg,"profileName","车主");if(!cfg.has("profileBio"))put(cfg,"profileBio","每次出发，都有回应");if(!cfg.has("address"))put(cfg,"address",true);if(!cfg.has("addressProvider"))put(cfg,"addressProvider","system");if(!cfg.has("amapKey"))put(cfg,"amapKey","");if(!cfg.has("location"))put(cfg,"location",true);if(!cfg.has("outsideEncoding"))put(cfg,"outsideEncoding","vehiclehub");for(String door:DOOR_KEYS){if(!cfg.has("normal_"+door))put(cfg,"normal_"+door,true);if(!cfg.has("ai_"+door))put(cfg,"ai_"+door,true);}
 Object[][] d={{"localDoorAudio",true},{"autoStart",true},{"wakeLock",true},{"requestLog",true},{"logContext",true},{"enabled",true},{"normal",true},{"ai",false},{"dedup",true},{"cooldown",15},{"single",true},{"stale",true},{"expiry",15},{"driving",true},{"timeout",10},{"fuel",true},{"temperature",true},{"vehicle",true},{"baseUrl","https://api.siliconflow.cn/v1"},{"key",""},{"model","Qwen/Qwen2.5-7B-Instruct"},{"openText","{door}已打开，请留意后方来车"},{"closeText","{door}已关闭"},{"persona","你是车主的随车语音伙伴。自然亲切，可以轻松调侃。根据当前开关门事件说一句不超过40字的中文。不要复述刚播过的普通提示。不要编造目的地、天气、故障或驾驶建议。没有可靠读数的字段不要猜测。只返回要播报的纯文本。"}};for(Object[] a:d)if(!cfg.has((String)a[0]))put(cfg,(String)a[0],a[1]);}
 public synchronized JSONObject config(){try{return new JSONObject(cfg.toString());}catch(Exception e){return new JSONObject();}}
 public synchronized void save(String text){try{JSONObject next=new JSONObject(text);cfg=next;defaults();ctx.getSharedPreferences("assistant",0).edit().putString("config",cfg.toString()).apply();generation.incrementAndGet();refreshLocation();note("设置","配置已保存，旧请求结果失效");}catch(Exception e){note("设置","配置保存失败");}}
 public synchronized void start(){if(started)return;started=true;poll=Executors.newSingleThreadScheduledExecutor();reader.doorListener=(door,value)->{ScheduledExecutorService worker=poll;if(worker!=null&&!worker.isShutdown())try{worker.execute(()->consumeDoor(door,value,"订阅"));}catch(RejectedExecutionException ignored){}};reader.connect();tts.connect(ctx);refreshLocation();poll.scheduleWithFixedDelay(()->{try{tick();}catch(Exception e){note("连接","采样暂不可用");}},1,1,TimeUnit.SECONDS);}
 void consumeDoor(int door,int value,String source){Integer change;long now=SystemClock.elapsedRealtime();synchronized(this){change=tracker.update(door,value,now);doors[door]=value;seen[door]=now;lastSample=now;}if(change!=null){note("门变化",DOOR_NAMES[door]+" → "+(change==1?"打开":"关闭")+" · "+source);event(door,change==1);}}
 void tick(){for(int i=0;i<4;i++){int[] v=reader.read(0x50004,15+i);if(v!=null&&v.length==1&&(v[0]==0||v[0]==1))consumeDoor(i,v[0],"轮询");}long now=SystemClock.elapsedRealtime();if(now-telemetryReadAt>=5000){captureTelemetry(config());telemetryReadAt=now;}if(now-lastSampleNote>30000){lastSampleNote=now;synchronized(this){note("门采样",java.util.Arrays.toString(doors)+" · "+reader.subscription+" · 最近成功采样距今 "+(now-lastSample)+"ms");}}}
 void enqueueNormal(String text,int door,boolean open,boolean useLocal){main.post(()->{if(normalQueue.size()>=8){note("普通提示","队列已满，跳过新提示");return;}normalQueue.addLast(()->{if(useLocal)localAudio.play(door,open);else tts.speak(text);});if(!draining){draining=true;drainNormal(SystemClock.elapsedRealtime());}});}
 void drainNormal(long since){if(normalQueue.isEmpty()){draining=false;return;}if(tts.busy||localAudio.busy){if(SystemClock.elapsedRealtime()-since>60000){normalQueue.clear();draining=false;note("普通提示","语音通道超时，清空等待队列");return;}main.postDelayed(()->drainNormal(since),250);return;}normalQueue.removeFirst().run();main.postDelayed(()->drainNormal(SystemClock.elapsedRealtime()),250);}

 synchronized void note(String kind,String text){JSONObject j=new JSONObject();put(j,"kind",kind);put(j,"text",text);put(j,"time",new java.text.SimpleDateFormat("HH:mm:ss",Locale.CHINA).format(new Date()));history.addFirst(j);while(history.size()>100)history.removeLast();ctx.getSharedPreferences("diagnostics",0).edit().putString("history",new JSONArray(history).toString()).apply();}
 public void reconnect(){if(!reader.connected()){reader.retry();note("保活","正在恢复车辆服务连接");}if(!tts.isReady()){tts.release();tts.connect(ctx);note("保活","正在恢复 TTS 连接");}}
 String beginRequest(JSONObject c,String source,JSONObject context){if(!c.optBoolean("requestLog",true))return "";String host="";try{host=new URL(c.optString("baseUrl")).getHost();}catch(Exception ignored){}return journal.begin(source,c.optString("model"),host,c.optBoolean("logContext")?context:null);}
 String recorded(JSONObject c,JSONObject data,String normal,String id)throws Exception{long began=SystemClock.elapsedRealtime();try{JSONObject outgoing=ModelClient.payload(c,data,normal);synchronized(this){lastPayload=outgoing.toString();lastContext=data.toString();}if(c.optBoolean("logContext",true))journal.payload(id,outgoing);ModelClient.Result result=ModelClient.send(c,outgoing);journal.update(id,"等待播报",200,SystemClock.elapsedRealtime()-began,result.text,result.usage);return result.text;}catch(Exception e){int status=e instanceof ModelClient.HttpFailure?((ModelClient.HttpFailure)e).code:0;String reason=status==402?"失败：账户欠费":status==401?"失败：密钥无效":status==429?"失败：请求限流":e instanceof java.net.SocketTimeoutException?"失败：请求超时":"失败："+e.getClass().getSimpleName();journal.update(id,reason,status,SystemClock.elapsedRealtime()-began,null,null);throw e;}}
 public synchronized void clearRequests(){journal.clear();lastPayload="{}";lastContext="{}";}
 public void modelTest(){JSONObject c=config();if(active.get()!=0){note("模型测试","已有请求，请稍后再试");return;}active.incrementAndGet();net.execute(()->{long start=SystemClock.elapsedRealtime();try{JSONObject synthetic=new JSONObject();put(synthetic,"event","synthetic_driver_door_closed");put(synthetic,"note","仅为虚构测试，不包含真实车况或位置");String id=beginRequest(c,"连接测试（虚构场景）",synthetic);String text=recorded(c,synthetic,"车门已关闭",id);journal.update(id,"测试成功（未播报）",-1,-1,null,null);note("模型测试","成功 · "+(SystemClock.elapsedRealtime()-start)+"ms · "+text+"（未播报）");synchronized(this){aiStatus="模型测试成功";}}catch(Exception e){note("模型测试","失败："+e.getClass().getSimpleName()+" "+e.getMessage());}finally{active.decrementAndGet();}});}
 public void audition(){main.post(()->tts.speak("你好，我是你的车门语伴。普通提示和智能问候，都已准备就绪。"));note("试听","已请求车机 TTS 播放");}
 public void stopSpeech(){generation.incrementAndGet();main.post(()->{normalQueue.clear();localAudio.stop();tts.stop();});note("播报","已停止，待返回文案已作废");}
 public void simulate(boolean open){note("演示",open?"模拟开门 · 不请求模型、不发声":"模拟关门 · 不请求模型、不发声");}
 public void refreshLocation(){JSONObject c=config();location.configure(c.optBoolean("enabled",true)&&c.optBoolean("location",true),c);}
 boolean movingOrUnknown(){Double speed=SignalDecoder.speed(reader.read(0x50004,0));return speed==null||speed!=0;}
 VehicleTelemetry captureTelemetry(JSONObject c){VehicleTelemetry telemetry=new VehicleTelemetry(reader::read,c);synchronized(this){latestTelemetry=telemetry.context;signalDiagnostics=telemetry.diagnostics;}return telemetry;}
 JSONObject snapshot(JSONObject c,int door,boolean open){JSONObject j=new JSONObject();put(j,"event",open?"door_open":"door_closed");put(j,"door",DOOR_NAMES[door]);put(j,"door_id",DOOR_KEYS[door]);put(j,"time",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss Z",Locale.CHINA).format(new Date()));put(j,"vehicle",captureTelemetry(c).context);if(c.optBoolean("location",true))put(j,"location",location.snapshot(true));return j;}
 void event(int door,boolean open){JSONObject c=config();long now=SystemClock.elapsedRealtime();long epoch=generation.get();if(!c.optBoolean("enabled"))return;boolean localEnabled=c.optBoolean("normal")&&c.optBoolean("normal_"+DOOR_KEYS[door],true);boolean aiEnabled=c.optBoolean("ai")&&c.optBoolean("ai_"+DOOR_KEYS[door],true);if(!localEnabled&&!aiEnabled)return;long token=doorGeneration.incrementAndGet(door);if(c.optBoolean("dedup")&&!tracker.accept(door,open,now,clamp(c,"cooldown",0,3600,15)*1000L)){note("去重","本次车门事件处于冷却期");return;}String normal=c.optString(open?"openText":"closeText").replace("{door}",DOOR_NAMES[door]).replace("主驾车门",DOOR_NAMES[door]);if(localEnabled&&!normal.trim().isEmpty()){lastLocal=now;enqueueNormal(normal,door,open,c.optBoolean("localDoorAudio",true));note("普通提示",c.optBoolean("localDoorAudio",true)?DOOR_NAMES[door]+(open?"打开":"关闭")+" · 本地预录音频":normal);}if(!aiEnabled)return;if(active.get()>=(c.optBoolean("single")?1:2)){note("AI","已有请求处理中，本次跳过");return;}if(c.optBoolean("driving")&&movingOrUnknown()){note("AI","当前车速未知或非零，按策略跳过");return;}if(localEnabled&&c.optBoolean("localDoorAudio",true))normal="已安排播放"+DOOR_NAMES[door]+(open?"打开":"关闭")+"的预录提示音，确切文案未提供";final String spoken=localEnabled?normal:"普通播报已关闭，本次未播本地提示";JSONObject data=snapshot(c,door,open);String requestId=beginRequest(c,DOOR_NAMES[door]+(open?"打开":"关闭"),data);synchronized(this){lastContext=data.toString();aiStatus="正在生成";}active.incrementAndGet();net.execute(()->{try{if(generation.get()!=epoch){journal.update(requestId,"已取消：发送前配置已变更",-1,-1,null,null);return;}if(c.optBoolean("location",true)&&c.optBoolean("address",true)){location.awaitAddress();if(generation.get()!=epoch){journal.update(requestId,"已取消：解析地址时配置已变更",-1,-1,null,null);return;}put(data,"location",location.snapshot(true));}String result=recorded(c,data,spoken,requestId);main.post(()->deliver(c,door,token,epoch,now,result,requestId));}catch(Exception e){synchronized(this){aiStatus="请求失败";}note("AI","请求未完成："+e.getClass().getSimpleName()+"，保留普通播报");}finally{active.decrementAndGet();}});}
 void deliver(JSONObject c,int door,long token,long epoch,long when,String text,String requestId){JSONObject current=config();if(!current.optBoolean("enabled")||!current.optBoolean("ai")||!current.optBoolean("ai_"+DOOR_KEYS[door],true)||generation.get()!=epoch){journal.update(requestId,"已丢弃：设置变更或停止播报",-1,-1,null,null);return;}if(c.optBoolean("stale")&&(doorGeneration.get(door)!=token||SystemClock.elapsedRealtime()-when>clamp(c,"expiry",3,120,15)*1000L)){journal.update(requestId,"已丢弃：文案过期或同门新事件",-1,-1,null,null);note("AI","返回文案已过期，已丢弃");return;}if(c.optBoolean("driving")&&movingOrUnknown()){journal.update(requestId,"已丢弃：车速未知或非零",-1,-1,null,null);note("AI","返回时车速未知或非零，已丢弃");return;}if(tts.busy||localAudio.busy||!normalQueue.isEmpty()){if(SystemClock.elapsedRealtime()-when<60000){main.postDelayed(()->deliver(c,door,token,epoch,when,text,requestId),300);}else {journal.update(requestId,"已丢弃：语音排队超时",-1,-1,null,null);note("AI","语音通道繁忙，放弃排队");}return;}int queued=tts.speak(text);journal.update(requestId,queued==0?"已交给 TTS（不代表播放完成）":"TTS 未就绪",-1,-1,null,null);synchronized(this){aiStatus="文案已交给 TTS";}note("AI 文案",text);}
 int clamp(JSONObject c,String k,int min,int max,int def){return Math.max(min,Math.min(max,c.optInt(k,def)));}
 String request(JSONObject c,JSONObject context,String normal)throws Exception{return ModelClient.request(c,context,normal);}

 public synchronized JSONObject state(){JSONObject j=new JSONObject();put(j,"connection",reader.status);put(j,"tts",tts.status());put(j,"subscription",reader.subscription);put(j,"telemetry",latestTelemetry);put(j,"signalDiagnostics",signalDiagnostics);put(j,"location",location.snapshot(cfg.optBoolean("location",true)));put(j,"ai",aiStatus);put(j,"requests",active.get());put(j,"context",lastContext);put(j,"lastPayload",lastPayload);put(j,"fresh",SystemClock.elapsedRealtime()-lastSample<4000);JSONArray ds=new JSONArray();for(int i=0;i<4;i++)ds.put(doors[i]==null||SystemClock.elapsedRealtime()-seen[i]>4000?JSONObject.NULL:doors[i]);put(j,"doors",ds);put(j,"events",new JSONArray(history));put(j,"requestHistory",journal.list());put(j,"serviceAlive",serviceHealth);put(j,"wakeHeld",wakeHeld);put(j,"serviceUptime",serviceUptime);put(j,"batteryExempt",ctx.getSystemService(android.os.PowerManager.class).isIgnoringBatteryOptimizations(ctx.getPackageName()));return j;}
 public synchronized void close(){if(poll!=null)poll.shutdownNow();reader.close();location.close();localAudio.stop();tts.release();generation.incrementAndGet();started=false;tracker.reset();for(int i=0;i<4;i++)doors[i]=null;}
}
